<#
  Instalador automatico de Modo Despierta (Windows Keep-Awake)
  Uso: irm <URL>/instalar_despierta.ps1 | iex
#>
$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "   Instalando Modo Despierta (Windows Keep-Awake) ☕       " -ForegroundColor Yellow
Write-Host "==========================================================" -ForegroundColor Cyan

$targetDir = Join-Path $env:LOCALAPPDATA "Despierta"
if (-not (Test-Path $targetDir)) {
    New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
}
$exePath = Join-Path $targetDir "despierta.exe"

# Cerrar instancia previa si estuviera en ejecucion
Get-Process -Name despierta -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Milliseconds 300

Write-Host "[1/3] Desplegando ejecutable autonomo (7 KB)..." -ForegroundColor Gray
$b64 = ""
[System.IO.File]::WriteAllBytes($exePath, [Convert]::FromBase64String($b64))

Write-Host "[2/3] Registrando comando Win + R ('despierta')..." -ForegroundColor Gray
$appPaths = "HKCU:\Software\Microsoft\Windows\CurrentVersion\App Paths"
New-Item -Path "$appPaths\despierta.exe" -Force | Out-Null
Set-ItemProperty -Path "$appPaths\despierta.exe" -Name "(Default)" -Value $exePath
New-Item -Path "$appPaths\despierta" -Force | Out-Null
Set-ItemProperty -Path "$appPaths\despierta" -Name "(Default)" -Value $exePath

Write-Host "[3/3] Agregando al PATH de usuario..." -ForegroundColor Gray
$userPath = [Environment]::GetEnvironmentVariable("Path", "User")
if ($userPath -notmatch [regex]::Escape($targetDir)) {
    [Environment]::SetEnvironmentVariable("Path", "$userPath;$targetDir", "User")
}

Write-Host ""
Write-Host " [OK] Instalado con exito!" -ForegroundColor Green
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host " COMO USARLO:" -ForegroundColor White
Write-Host "   1. Presiona [Win + R]" -ForegroundColor Yellow
Write-Host "   2. Escribe 'despierta' y presiona Enter" -ForegroundColor Yellow
Write-Host "   3. Aparecera el icono del cafe en el Systray" -ForegroundColor Yellow
Write-Host "   4. Clic izquierdo en el icono para desactivar" -ForegroundColor Yellow
Write-Host "==========================================================" -ForegroundColor Cyan

